import {STAT_KEYS,STAT_NAMES,IV_MAX,EV_MAX,EV_TOTAL,totalEVs,ivJudgement} from './training.js';
import {computeStats} from './battle.js';
const RADAR_KEYS=['hp','atk','def','spe','spd','spa'];
const pos=(index,radius)=>{const angle=-Math.PI/2+index*Math.PI/3;return {x:210+Math.cos(angle)*radius,y:173+Math.sin(angle)*radius};};
const points=values=>RADAR_KEYS.map((key,i)=>{const p=pos(i,values(key)*105);return p.x.toFixed(2)+','+p.y.toFixed(2);}).join(' ');
export function radarMarkup(values,max,mode){
 const title=mode==='iv'?'Potentiel individuel · IV':'Points d’effort · EV';
 return `<svg class="training-radar" viewBox="0 0 420 350" role="img" aria-label="${title}"><title>${title}</title><desc>${RADAR_KEYS.map(key=>STAT_NAMES[key]+' : '+values[key]+' sur '+max).join(', ')}</desc>${[.25,.5,.75,1].map(r=>`<polygon class="radar-grid" points="${points(()=>r)}"/>`).join('')}${RADAR_KEYS.map((key,i)=>{const p=pos(i,105);return `<line class="radar-axis" x1="210" y1="173" x2="${p.x}" y2="${p.y}"/>`;}).join('')}<polygon class="radar-shape" points="${points(key=>values[key]/max)}"/>${RADAR_KEYS.map((key,i)=>{const p=pos(i,values[key]/max*105),label=pos(i,143);const anchor=label.x>215?'start':label.x<205?'end':'middle';return `<circle class="radar-point" cx="${p.x}" cy="${p.y}" r="3"/><text class="radar-label" x="${label.x}" y="${label.y-4}" text-anchor="${anchor}">${STAT_NAMES[key]}</text><text class="radar-value" x="${label.x}" y="${label.y+13}" text-anchor="${anchor}">${values[key]} / ${max}</text>`;}).join('')}</svg>`;
}
export function mountTrainingPanel(root,{record,level,base,name,nature=null}){
 const center=root.querySelector('#profile-center'),original=[...center.childNodes];let mode=null,origin=null;
 function close(){mode=null;center.classList.remove('training-open');center.replaceChildren(...original);root.querySelectorAll('[data-training]').forEach(b=>b.setAttribute('aria-pressed','false'));origin?.focus({preventScroll:true});}
 function show(next,button){if(mode===next){close();return;}mode=next;origin=button;const iv=mode==='iv',values=iv?record.ivs:record.evs,max=iv?IV_MAX:EV_MAX,total=STAT_KEYS.reduce((sum,key)=>sum+values[key],0),withoutEV=computeStats(base,level,{ivs:record.ivs},nature),stats=computeStats(base,level,record,nature);
 center.classList.add('training-open');center.innerHTML=`<section class="training-panel ${iv?'training-iv':'training-ev'}" aria-label="${iv?'IV':'EV'} de ${name}"><header class="training-header"><div><span>${iv?'POTENTIEL INNÉ':'ENTRAÎNEMENT'}</span><h3>${iv?'Valeurs individuelles':'Points d’effort'}</h3></div><button type="button" data-training-close aria-label="Revenir au Pokémon">×</button></header><div class="training-summary"><strong>${total} <small>/ ${iv?186:EV_TOTAL}</small></strong><span>${iv?'Potentiel total':EV_TOTAL-total+' EV encore disponibles'}</span></div>${radarMarkup(values,max,mode)}${!iv?`<div class="training-total-bar" role="progressbar" aria-label="EV totaux" aria-valuemin="0" aria-valuemax="510" aria-valuenow="${totalEVs(record.evs)}"><i style="width:${total/EV_TOTAL*100}%"></i></div>`:''}<dl class="training-values">${STAT_KEYS.map(key=>`<div><dt>${STAT_NAMES[key]}</dt><dd><b>${values[key]}</b><span> / ${max}</span></dd><small>${iv?ivJudgement(values[key]):'+'+(stats[key]-withoutEV[key])+' point'+(stats[key]-withoutEV[key]>1?'s':'')+' au niv. '+level}</small></div>`).join('')}</dl><p class="training-note">${iv?'Fixés à la première capture de cette espèce. Les doublons conservent ses IV. Un IV de 31 est parfait.':'Gagnés en battant des Pokémon : chaque espèce donne ses propres EV. Seuls les participants encore debout en reçoivent. Maximum 252 par statistique et 510 au total. Au niveau 100, 4 EV apportent 1 point de statistique.'}</p><small class="training-neutral">Les six statistiques de combat intègrent ces valeurs · nature neutre.</small></section>`;
 root.querySelectorAll('[data-training]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.training===mode)));center.querySelector('[data-training-close]').focus({preventScroll:true});center.scrollIntoView({block:'start',behavior:'auto'});
 }
 root.addEventListener('click',event=>{const button=event.target.closest('[data-training]');if(button&&root.contains(button)){show(button.dataset.training,button);return;}if(event.target.closest('[data-training-close]'))close();});
}
